const express = require('express');
const _ = require('lodash');
const { execSync } = require('child_process');

const app = express();
app.use(express.json());

// Internal CLI tool wrapper - processes job configurations from other services
// Used by the build-system namespace to accept build configs

const defaultConfig = {
  compiler: {
    optimization: 'O2',
    target: 'x86_64',
    flags: []
  },
  output: {
    format: 'binary',
    path: '/tmp/builds'
  },
  metadata: {
    version: '1.0.0'
  }
};

function deepMergeConfig(target, source) {
  // Recursively merge source into target
  for (const key in source) {
    if (source.hasOwnProperty(key)) {
      if (typeof source[key] === 'object' && source[key] !== null && !Array.isArray(source[key])) {
        if (!target[key]) target[key] = {};
        deepMergeConfig(target[key], source[key]);
      } else {
        target[key] = source[key];
      }
    }
  }
  return target;
}

// Endpoint accepts build configuration from trusted internal services
app.post('/api/v1/configure-build', (req, res) => {
  const userConfig = req.body;

  // Validate required fields
  if (!userConfig.compiler || !userConfig.compiler.target) {
    return res.status(400).json({ error: 'Missing compiler.target' });
  }

  // Merge user config with defaults
  const config = deepMergeConfig({}, defaultConfig);
  deepMergeConfig(config, userConfig);

  // Execute build with merged config
  const cmd = `${config.compiler.optimization === 'O0' ? 'gcc' : 'gcc'} -${config.compiler.optimization} -o ${config.output.path}/out main.c`;

  try {
    // Note: command is constructed from config values but optimization level is constrained
    const result = execSync(cmd, { timeout: 30000, encoding: 'utf-8' });
    res.json({ status: 'success', output: result });
  } catch (err) {
    res.status(500).json({ error: 'Build failed', details: err.message });
  }
});

// Health check endpoint
app.get('/healthz', (req, res) => {
  res.json({ status: 'healthy', polluted: ({}).polluted || false });
});

// Status endpoint shows current prototype state (for debugging)
app.get('/api/v1/status', (req, res) => {
  const obj = {};
  res.json({
    clean: Object.keys(obj).length === 0,
    proto_check: obj.polluted,
    constructor_check: obj.constructor === Object
  });
});

app.listen(8080, () => {
  console.log('Build config service running on :8080');
});
